"""Configure Android platform generated by Flutter in GitHub Actions.

The source stays a native Flutter application, never an embedded website.
"""
import sys
from pathlib import Path

if "--signing" in sys.argv:
    # Release signing from environment variables set by the workflow.
    gradle = Path("android/app/build.gradle.kts")
    source = gradle.read_text()
    if "create(\"release\")" not in source:
        block = (
            "    signingConfigs {\n"
            "        create(\"release\") {\n"
            "            storeFile = file(System.getenv(\"ANDROID_KEYSTORE_PATH\"))\n"
            "            storePassword = System.getenv(\"ANDROID_KEYSTORE_PASSWORD\")\n"
            "            keyAlias = System.getenv(\"ANDROID_KEY_ALIAS\")\n"
            "            keyPassword = System.getenv(\"ANDROID_KEY_PASSWORD\")\n"
            "        }\n"
            "    }\n\n"
        )
        source = source.replace("    buildTypes {", block + "    buildTypes {", 1)
        source = source.replace('signingConfig = signingConfigs.getByName("debug")',
                                'signingConfig = signingConfigs.getByName("release")')
        gradle.write_text(source)
    print("Configured permanent release signing")
    raise SystemExit(0)

android = Path("android")
manifest = android / "app/src/main/AndroidManifest.xml"
if not manifest.exists():
    raise SystemExit("Flutter must generate Android project before this step")
raw = manifest.read_text()
permissions = (
    '    <uses-permission android:name="android.permission.INTERNET" />\n'
    '    <uses-permission android:name="android.permission.CAMERA" />\n'
    '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n'
    '    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n'
    '    <uses-permission android:name="android.permission.ACCESS_LOCAL_NETWORK" />\n'
)
raw = raw.replace("<application", permissions + "    <application", 1)
raw = raw.replace('android:label="nohut_personel"',
                  'android:label="Nohut Personel"')
raw = raw.replace("<application", '<application android:usesCleartextTraffic="true"', 1)
# Cleartext is LAN-only. Dart validates that all QR hosts are private IPv4.
manifest.write_text(raw)

gradle = android / "app/build.gradle.kts"
if not gradle.exists():
    raise SystemExit("Flutter generated an unknown Android Gradle template")
source = gradle.read_text()
if "isCoreLibraryDesugaringEnabled = true" not in source:
    source = source.replace("compileOptions {",
        "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", 1)
if "coreLibraryDesugaring(" not in source:
    source += (
        '\ndependencies {\n'
        '    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n'
        '}\n'
    )
source = source.replace("minSdk = flutter.minSdkVersion", "minSdk = 23")
# Keep API target at Android 16 for now. Android 17-targeted updates will
# request ACCESS_LOCAL_NETWORK at runtime before opening a LAN socket.
source = source.replace("targetSdk = flutter.targetSdkVersion",
                        "targetSdk = 36")
gradle.write_text(source)
# Flutter create generates a generic MyApp widget test which does not match the
# native NohutPersonelApp. Project-specific tests are in personel_test.dart.
template_test = Path("test/widget_test.dart")
if template_test.exists():
    template_test.unlink()
print("Configured LAN, camera, notifications and desugaring for native app")
